interface FAQItem {
  question: string;
  answer: string;
}

interface FAQBlockProps {
  /** FAQ items */
  items: FAQItem[];
  /** Section heading */
  heading?: string;
  /** Section subtitle */
  subtitle?: string;
  /** Layout variant */
  layout?: "single" | "two-column";
  className?: string;
